[McpServerToolType]
public class PlcWriteTools
{
    [McpServerTool(Name = "plc_write", ReadOnly = false, Destructive = true, OpenWorld = false,
        UseStructuredContent = true, OutputSchemaType = typeof(PlcGuardedWriteResponse))]
    [Description("Execute up to 50 ordered PLC software writes against one verified already-open project. Omitted dryRun or dryRun:false executes; use dryRun:true to preview effects, dependsOn and guards without mutation. No confirmation prompt is sent. Operations: update_block_logic (blockPath, content, expectedContentHash, optional format xml (default) | source | sd; sd imports the bundle of get_block_content sd with PlcBlockComposition.ImportFromDocuments(..., ImportDocumentOptions.Override): exactly one .s7dcl declaring the target block, optionally its .s7res, no .xml; a bundle without .xml in format xml still takes that route as before), update_type_content (typePath, content, expectedContentHash), create_tag_table/delete_tag_table (tableName), create_tag/update_tag/delete_tag (create_tag and update_tag take an optional comment with commentCulture: the PlcTag.Comment text item of that culture (LanguageSettings.Languages, Comment.Items.Find) gets the text, read back; a culture that is no active project language is passed on with a warning and TIA Portal decides, one it has no text item for fails (create_tag then deletes the tag it created, update_tag keeps its other changes), one TIA Portal does not know is refused before anything changes; create_tag, delete_tag and a commented update_tag are verified by re-reading the tag table and the comment, check tag), move_tag (tableName, name, targetTableName, optional folderPath and targetFolderPath; re-created in the target table with its data type, address, external-access flags and multilingual comment in one transaction that a failure rolls back; other attributes are not carried; verified by re-reading both tables, check tag), create_user_constant/update_user_constant/delete_user_constant (tableName, name), create_block (blockPath, blockType, language, obEventClass for OB; the worker re-resolves the created block by its path, which is the verification, check block; it is not compiled), delete_block (verified by re-reading the path: it must be gone, check block; a later item that creates the same block name in any group supersedes it, block names being unique per PLC), create_block_group, delete_block_group (blockPath), create_watch_table/delete_watch_table (tableName, optional folderPath group path), create_watch_table_group/delete_watch_table_group (folderPath names the group), update_watch_table_content/update_force_table_content (tableName, content, expectedContentHash from get_watch_table_content/get_force_table_content; entries are added, changed and removed only through this SimaticML round trip, and force tables are edited offline only, never forced online), update_program (optional plcName; PlcSoftware.UpdateProgram upgrades block instructions to the latest version the PLC firmware supports, offline); granular block edits: add_interface_member (blockPath+section or typePath, memberPath, dataType, optional startValue, comment+commentCulture, insertBefore), update_interface_member (newName, dataType, startValue, clearStartValue, comment), delete_interface_member — a SimaticML edit of the exported document imported through update_block_logic/update_type_content with the export's hash and verified by re-reading the member; optional expectedContentHash (xml); update_db_member (blockPath, memberPath at any depth incl. array elements and multi-instances, startValue and/or externalAccessible, externalVisible, externalWritable, retain, setPoint; native Member.SetAttribute, read back); create_db_snapshot (blockPath of a global or instance DB, optional memberPath and maxElements for the returned values; the PLC must be online (plc_tia_online go_online): ValueService.CreateSnapshot() takes the actual values, TIA Portal stores them as the DB's snapshot in the offline project (info guard plc_stores_db_snapshot; nothing is written to the PLC, no start value changes), and the result is the exported snapshot, verified by re-reading it (check dbSnapshot); adopted from BetterTIA/watch watch_db, members bound at runtime, not live-tested); set_network_text (blockPath of an OB, FB or FC, networkNumber 1-based, title and/or comment, optional culture, expectedContentHash xml; a language the network has no text in yet is added) and replace_network_text (blockPath, replacements [{ find, replace }] 1-100 applied in one pass, literal and case-sensitive, longest find first so swaps work; optional culture (omitted: every language) and textScope networks (default) | all (also the block title/comment and the GRAPH sequence, step and transition texts)): Openness has no setter for network texts, so the exported SimaticML is edited host-side and imported through update_block_logic against the export's hash (know-how-protected blocks refused; an edit that changes nothing is refused before anything runs; info guard plc_text_edit_reimports_block: the import can leave the instance DB and callers inconsistent, compile afterwards); verified by re-export (check networkText: every changed text reads back at its place and language, contentHash reported); adopted from BetterTIA/writer, not live-tested; rename_members (blockPath or typePath, memberRenames [{ memberPath, newName, section? }] 1-100, optional expectedContentHash xml): renames several interface members together (swaps and rotations through temporary names) and updates the object's own accesses as the TIA Portal editor does (LocalVariable symbols and instances in LAD/FBD/STL/SCL/GRAPH networks, #operands in GRAPH actions); accesses in other blocks, HMI tags, watch tables and technology objects are not updated (info guard plc_changes_interface; read analyze_change_impact first and compile afterwards); instance and array DBs refused; verified by re-reading the interface (check renamedMembers); adopted from BetterTIA/writer RenameMembers, not live-tested; rename_tags (optional plcName, renames [{ name, newName }] 1-200: PLC tags by name across every tag table of the PLC) and rename_objects (optional plcName, renames: blocks, PLC data types and technology objects by name, a name in more than one kind is ambiguous): every object resolved before anything changes, then SetAttribute(\"Name\") per step (GetAttributeInfos writability check and read-back) in one ExclusiveAccess transaction, with swaps, rotations and chains through temporary names (zzTmp_...); any failed step rolls every rename back and the failure reports the names afterwards; fail-safe tags and F-blocks follow TIA Portal's safety login rule (info guard plc_batch_rename; users re-bind by name at the next compile, HMI tags and watch tables are not changed); verified by re-reading the tag tables (rename_tags) or by the transaction's read-back (rename_objects), check batchRename; adopted from BetterTIA/writer, not live-tested; replace_tag_comments (optional plcName, tableName with folderPath for one table, replacements [{ find, replace }] 1-100 in one pass as replace_network_text, optional culture): every PLC tag comment text in scope that a find changes is set through MultilingualTextItem.Text and read back in one ExclusiveAccess transaction (rollback on failure); the preview lists every changed text from read_tag_comments, an item that changes nothing is refused; verified by re-reading the comments (check tagComments); tags of the PLC's own tag tables only; it changes existing texts only, so give a tag without a comment its first text with update_tag comment+commentCulture; adopted from BetterTIA/writer, not live-tested; SIMATIC SD network edits (the path the Siemens V21 simatic-sd skill names for adding LAD/FBD/SCL networks to existing blocks; not live-tested): insert_network (blockPath, code, optional language, position 1-based (omitted appends), expectedContentHash sd), replace_network (blockPath, networkNumber, code, optional language (omitted keeps the network's), expectedContentHash sd; the network's pragma keys such as S7_NetworkTitle/S7_NetworkComment stay) and delete_network (blockPath, networkNumber, expectedContentHash sd; the network and its pragma are removed): planned host-side on the get_block_content sd export (code: a RUNG body, a full NETWORK ... END_NETWORK with or without its pragma, or SCL statements; only the outer wrappers and the S7_Language pragma are stripped, inner { S7_Templates := \"...\" } pragmas stay; one network per code; unbalanced RUNG/END_RUNG or NETWORK/END_NETWORK and S7_NetworkTitle/S7_NetworkComment keys are refused, everything else is TIA Portal's to accept), imported through update_block_logic format sd against the export's hash; the .s7res is never changed; several items on one block chain through dependsOn and are re-planned (a later item numbers the networks as the earlier ones left them); info guards plc_text_edit_reimports_block (compile afterwards), plc_sd_reimports_export_form (untouched networks in an export form reported not to re-import; not reproduced live on V21 for GT/EQ_Contact, Move, P_Trig/N_Trig, TON/TOF, Add) and plc_s7dcl_import_may_alter; verified by re-export (check networkCode: network count, position and language must match; the message reports codeMatchesExport true|false with both texts in expected/actual, as information, because the V21 export form of an instruction is reported to differ from its import form and TIA Portal reformats whitespace; contentHash sd reported). create_block_from_document (targetGroupPath, content: an sd bundle with the .s7dcl and, optionally, the .s7res (TIA Portal's own export of a block without texts has none); every culture in the .s7res must be a project language (a culture the project lacks failed the import live; the item reports the cultures it holds), optional overwrite): ImportFromDocuments into that group; a block of the declared name anywhere in the PLC is refused unless overwrite:true (info guard plc_sd_document_replaces_block); verified by re-exporting it in sd (check createdBlock, contentHash sd). A header S7_Safety := \"TRUE\" marks a fail-safe block for every SD write (the safety rules below apply). create_instance_db (blockPath, instanceOfName, optional number); rename_block (newName); renumber_block (number or autoNumber:true); copy_block (newName, optional targetGroupPath, number) and move_block (targetGroupPath) by SimaticML export/import, refusing know-how-protected blocks (their export carries only the interface); move_tag_table (tableName, folderPath, targetFolderPath) by export/delete/import with re-import on failure. OPC UA export (not live-tested; idea from heilingbrunner/tiaportal-mcp, MIT): export_opcua_xml (filePath, optional plcName and overwrite) writes the OPC UA data of the PLC's CPU as XML through Project.HwUtilities.Find(\"OPCUAExportProvider\") and OpcUaExportProvider.Export(DeviceItem, FileInfo), bound at runtime (api_member_missing when absent); staged, moved into place and re-hashed like export_tag_table, an existing file needs overwrite:true (info guard plc_export_overwrites_file); TIA Portal is reported to need the PLC offline. Tag tables as SimaticML files (not live-tested): export_tag_table (tableName, optional folderPath, filePath, overwrite; PlcTagTable.Export(FileInfo, ExportOptions.None) into a temporary file, staged next to the target, moved into place and re-hashed; an existing file needs overwrite:true, info guard plc_export_overwrites_file) and import_tag_table (filePath, optional folderPath, tableName and overwrite; PlcTagTableComposition.Import(FileInfo, ImportOptions) bound at runtime, of a private copy of the file, in one ExclusiveAccess transaction that a failed postcondition rolls back; overwrite:true imports with ImportOptions.Override (info guard plc_import_replaces_tag_table); tableName names the table the file holds and is then checked: it must not exist without overwrite and must be in the folder afterwards; verified by re-reading the tag tables, check tagTable); the CSV export export_tag_tables_csv stays. External sources (not live-tested): import_external_source (absolute local filePath of a .scl, .awl, .db or .udt file, optional sourceName defaulting to the file name, plcName, unitName; PlcExternalSourceComposition.CreateFromFile), generate_blocks_from_source (sourceName, optional generateOption None|KeepOnError and targetGroupPath block or PLC data type group; creates or overwrites every block and PLC data type the source declares), delete_external_source (sourceName; generated blocks stay), export_source_file (filePath, blockPaths and/or typePaths of one PLC scope, optional withDependencies and overwrite; GenerateSource into a temporary file next to the target, then moved into place). Group renames (not live-tested): rename_block_group (blockPath of the group), rename_type_group (typePath of the group), rename_tag_table_group (folderPath, optional unitName) and rename_watch_table_group (folderPath), each with newName, through SetAttribute(\"Name\") after a GetAttributeInfos writability check, read back. Group and software unit containers (not live-tested): create_type_group and delete_type_group (typePath of the group, e.g. PLC_1/Types/Motion or PLC_1/Units/U1/Types/Motion), create_tag_table_group and delete_tag_table_group (folderPath, optional plcName, unitName); the parent of a create must exist; deleting a group that is not empty removes everything inside it (info guard plc_deletes_group_contents). create_software_unit, delete_software_unit (unitName, optional plcName; a delete removes the unit's blocks, types, tag tables and external sources, info guard plc_deletes_group_contents) and rename_software_unit (unitName, newName; SetAttribute(\"Name\") with writability check and read-back). Each create is read back with Find(name), each delete must be gone afterwards. File exports from existing reads (not live-tested): export_tag_tables_csv, export_watch_tables_csv and export_force_tables_csv (filePath ending in .csv, optional plcName, tableName, folderPath, csvDelimiter, rawCells, overwrite; the tag CSV adds one Comment[culture] column per comment language read_tag_comments returns; RFC 4180, UTF-8 with BOM, a cell starting with =, +, -, @, tab or CR gets a leading ' unless rawCells) and export_blocks (directoryPath, optional plcName, blockPath or typePath group, format xml|source, maxElements, overwrite; one file per exported document below a project-tree mirror, each with its SHA-256). Every file is written through a temporary file and moved into place; an existing file is refused unless overwrite:true; drive paths and UNC shares (\\\\server\\share\\...) are accepted, device paths (\\\\?\\, \\\\.\\) are refused. Alarms, text lists and ProDiag supervisions (not live-tested): update_text_list (textListName, optional newName, listRange, comment with commentCulture; every requested member must be writable per GetAttributeInfos and a new name must be free among the user and system lists, checked before the first change; the rename runs first and everything is read back) and delete_text_list (textListName); system text lists are refused; a user text list is created with library_write instantiate_master_copy target kind textLists; update_text_list_cells, update_alarm_text_cells and update_supervision_cells (cellEdits [{ sheet, cell, expected, value, kind? }] and expectedWorkbookHash from the matching read_*_workbook with the same plcName, blockPath, textListNames, cultures and exportOption; update_text_list_cells requires textListNames, user text lists only, and exports and imports only those lists) export the workbook, refuse a changed hash or an unexpected cell value, patch only the edited cells, import the whole workbook with TIA Portal's XLSX import and re-export it, all under ExclusiveAccess, and fail when the re-export misses an edit or changed any other cell (result.unrequestedChanges); they cannot follow another change of the same PLC in one call; export_text_lists, export_alarm_texts, export_alarm_classes and export_supervisions (filePath, optional overwrite; TIA Portal writes a temporary file in the target directory that is moved into place, and an existing file is replaced only with overwrite:true, never through a link) and import_text_lists, import_alarm_texts (optional exportOption for its verification re-export), import_alarm_classes, import_supervisions and import_supervision_settings (filePath): TIA Portal decides what an import changes; the server imports a private copy of the file (result bytes and sha256 are that copy's) and re-exports the same kind right after it: importCheck.outcome verified (every imported row, columns matched by header, or for alarm classes the whole file, came back; check importedRows or fileHash), contradicted (an imported row is absent: notVerified, verification success false), inconclusive (layouts differ, the alarm-class file differs, or the verification export failed; check trusted with a warning) or notReadBack (import_supervision_settings and import_alarm_texts without exportOption have no documented export; check trusted with a warning); the import itself has changed the project in every case. set_prodiag_assignment (proDiagFb and the target of get_prodiag_assignment; read back by FB name, a value that does not read back as a name is notVerified) and export_prodiag_info (blockPath of a ProDiag FB, directoryPath that does not exist yet; CodeBlock.ExportProDIAGInfo writes CSV files into it, each re-hashed; an export that writes no file fails postcondition_failed). Every alarm write takes portalConfirmations (decline, the default: a TIA Portal dialog is answered No and fails the item; accept: Yes, with a warning); result.portalConfirmations records each. Alarm classes are project-wide (no plcName, standalone projects only). System diagnostics settings (issue #19; project-wide, no plcName, standalone projects only; not live-tested): export_system_diagnostics_settings (filePath, optional overwrite, portalConfirmations) and import_system_diagnostics_settings (filePath, portalConfirmations) call SystemdiagnosticsSettingsDataProvider.Export(FileInfo)/Import(FileInfo), the provider found among the Project's GetServiceInfos() (not listed: unsupported_capability), with the same caller-file rules as the alarm classes (staged export, overwrite:true, re-hash; import of a private copy verified by a byte compare of a re-export); result State Success succeeds, Warning succeeds with a warning, anything else fails; no file extension is required (none is documented; TIA Portal may refuse one). OPC UA server interfaces and access rules (issue #24; not live-tested; PlcSoftware OpcUaProvider service, members bound at runtime, a missing one fails api_member_missing with nothing changed; info guard plc_opcua_changes_server, plc_opcua_lowers_access when a restriction is relaxed or a permission granted): create_opcua_interface (interfaceKind server|simatic|referenceNamespace, interfaceName; ServerInterfaceComposition/SimaticInterfaceComposition.Create(String), ReferenceNamespaceComposition.Create(String, FileInfo) with filePath (required for referenceNamespace; for a server interface an optional XML imported right after the create)), delete_opcua_interface, export_opcua_interface (filePath, overwrite; Export(FileInfo) staged and re-hashed), import_opcua_interface (server or referenceNamespace, filePath; Import(FileInfo) of a private copy, verified by a byte compare of a re-export, otherwise notVerified), set_opcua_interface (enabled, useStringNodeIds, generateNodes, newName through SetAttribute after a GetAttributeInfos writability check, read back), set_opcua_namespace_restriction (namespaceUri; sessionRequired, signingRequired, encryptionRequired, applyRestrictionsToBrowse, read back), create_opcua_role (roleName, definingNamespace; RoleMappingComposition.Create), add_opcua_standard_role (roleName; AddStandardOpcUaRole), delete_opcua_role, set_opcua_role (roleName; newRoleName, definingNamespace, projectRole via SetRoleName/SetDefiningNamespace/SetProjectRole, read back) and set_opcua_namespace_permission (roleName, namespaceUri, permission, enabled; NamespacePermission.SetPermission(String, Boolean), read back through the property of that name when it is one of Browse, Read, Write, Call, ReceiveEvents, ReadRolePermissions, otherwise notVerified); every item takes optional plcName (the only PLC when omitted). Further download variants and the PLC master secret (issue #16; not live-tested): download_to_folder (directoryPath, an existing absolute directory; optional plcName, rhSystem (true: the R/H system's RHDownloadProvider), overwrite, portalConfirmations): DownloadProvider.Download(DirectoryInfo, DownloadConfigurationDelegate) writes the download data into the folder, no device is touched; a directory that is not empty is refused unless overwrite:true, and junctions, links and network locations are checked and reported like the other directory exports; download configurations get the built-in plc_download answers, any other one aborts; verified by the files the call wrote (re-hashed). set_plc_master_secret_online (passwordVariable: an environment variable NAME or { credential: \"TiaMcp/...\" }, never the secret) and reset_plc_master_secret_online (both with optional portalConfirmations; TIA Portal dialogs of the three issue #16 operations are answered decline (default: No, recorded, the item fails) or accept (Yes, recorded, a warning)): OnlineProvider.SetPlcMasterSecret(SecureString) / ResetPlcMasterSecret() on a PLC that is Online (connect first with plc_tia_online go_online; otherwise state_changed); OnlineControl (read-write and full), acknowledge guard plc_master_secret_online: read-write asks the human for every such call, full runs it under policy; the secret cannot be read back, so the item is notVerified (success false). Downloads to a controller stay with plc_download (rhTarget primary|backup for an R/H system). Loadable files (issue #26; not live-tested): generate_loadable (filePath, target Plc|PlcSim, exactly one of blockPaths (blocks of the non-unit program, one PLC) or unitNames (software units), optional plcName (default: the PLC the block paths name, else the only PLC) and overwrite): LoadableProvider.GenerateLoadable(FileInfo, IEnumerable<PlcBlock> | IEnumerable<PlcUnit>, TargetOption), the provider found among the PlcSoftware's GetServiceInfos() (not listed: unsupported_capability), the overload and the TargetOption member bound at runtime (missing: api_member_missing; TargetOption.None is documented to throw and is not offered); the file is written next to the target, moved into place without overwriting unless overwrite:true and re-hashed (result sha256, verification check file); a call that writes no file fails postcondition_failed. Project block-compilation settings (project-wide, no plcName, standalone projects only; not live-tested): set_project_compilation_settings (simulationDuringBlockCompilation and/or virtualPlcDuringBlockCompilation, true or false): sets \"Simulation während Bausteinübersetzung unterstützen\" (PlcSimulationSettingsProvider.IsSimulationDuringBlockCompilationEnabled, which Siemens' PLCSIM Advanced getting-started asks for before a Softbus download) and the virtual PLC flag (VirtualPlcSettingsProvider.IsVirtualPlcDuringBlockCompilationEnabled) through Project.GetService<T>(), the providers get_project_status reads as compilationSettings; the write is bound on the live provider (a writable property, else an attribute GetAttributeInfos lists as writable, else api_member_missing with nothing changed), result.settings has before, after, route and signature per setting, and a different read-back fails postcondition_failed (check compilationSettings). File paths are absolute drive or UNC share (\\\\server\\share\\...) paths, checked lexically; device (\\\\?\\, \\\\.\\, \\??\\) and alternate-data-stream paths, reserved device names and segments ending in a space or a dot are refused; a mapped network drive or a link on the way is allowed and reported (info guard plc_file_on_network_or_link). Technology objects (not live-tested; every TO-specific Siemens member is bound at runtime and fails closed with unsupported_capability): create_technology_object (name, technologyType, version, optional folderPath; TechnologicalInstanceDBComposition.Create(name, type, version); the accepted version depends on the CPU firmware (live V21 2026-11-02: a CPU 1516-3 PN/DP FW V2.9 rejected TO_PositioningAxis 10.0 and accepted 6.0) and is never guessed), delete_technology_object, rename_technology_object (newName), create/delete/rename_technology_object_group (folderPath; renames need Name listed writable by GetAttributeInfos), set_technology_object_parameter (name, parameterName and value converted to exactly the runtime type of the current value, or tableName and tagName for a PlcTag value; read back with a fresh Find, a different read-back fails postcondition_failed; Actor.* parameter writes do not connect hardware), connect_technology_object_hardware (connectionInterface actor|sensor|torque|measuringInput|outputCam|ident, resolving only the providers that interface needs (sensor: the axis provider first, the encoder provider as the alternative), and connectionKind address|module|modules|channel|tag|dbMember with that overload's fields; verified by reading the interface back: connected, and the overload's documented target property reads the requested target, otherwise postcondition_failed) and disconnect_technology_object_hardware, export_technology_object (filePath, optional overwrite) and import_technology_object (filePath, optional folderPath; overwrite:true imports with ImportOptions.Override) as SimaticML files at absolute drive or UNC share paths (device paths and reserved device names refused; a mapped network drive is used with a warning; an existing export file needs overwrite:true), update_technology_object_content (content and expectedContentHash from get_technology_object_content; Import with ImportOptions.Override). Compile the PLC with compile_check afterwards. CPU protection (offline project, effective after plc_download; passwords only from password sources, never as values, never generated; not live-tested; every member bound at runtime by exact signature, a missing one fails api_member_missing with nothing changed): set_plc_access_level (accessLevel FullAccessIncludingFailsafe, FullAccess, ReadAccess, HMIAccess or NoAccess, optional plcName; resetAccessLevelPasswords [levels] with ResetPassword(level) first, then PlcProtectionAccessLevel, then optional accessLevelPasswords { level: source } with PlcAccessLevelProvider.SetPassword(level, SecureString) (live V21 2026-11-02: TIA Portal accepts a level's password call only while the current level is less open than it, and every level needs its own password; a failed SetPassword restores the level read before); levels more open than accessLevel that the call omits come from the server password map (purpose = level name); before and after are read where readable, a different read-back fails postcondition_failed, an unreadable one is readBack unreadable; a matched read-back is the item's verification, check readBack; result.calls lists every member called, result.passwordSources the source tokens), protect_plc_confidential_data (passwordVariable, the master secret; PlcMasterSecretConfigurator.Protect(SecureString); allConfiguration:true uses ProtectAllPlcConfigurationWithPassword, or ProtectAllPlcConfiguration() without passwordVariable), change_plc_confidential_data_password (passwordVariable current, newPasswordVariable new; ChangePassword(SecureString, SecureString)) and disable_plc_confidential_data_protection (optional plcName; Unprotect(SecureString) with passwordVariable, else Unprotect(); allConfiguration:true calls UnprotectAllPlcConfiguration(); readBack notAvailable, MasterSecretConfiguration is in observedBefore/observedAfter). The confidential-data operations take the map's purpose PlcMasterSecretPassword when passwordVariable is omitted. Lowering protecti